#!/usr/bin/env node
// Builds a silent walkthrough from screenshots captured from the real dashboard.
// The source images are generated by `npm run docs:captures` in a disposable project.
import { copyFile, mkdir, rm } from 'node:fs/promises';
import { spawnSync } from 'node:child_process';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const imageRoot = path.join(root, 'docs', 'assets', 'guide');
const output = path.join(root, 'docs', 'assets', 'nexus-linkedin-usage-demo.mp4');
const frameRoot = path.join(root, '.tmp-linkedin-usage-frames');
const scenes = [
  ['workspace.png', '1  Workspace: describe the task'],
  ['agent-memory.png', '2  Agents: choose a role and its context'],
  ['memory.png', '3  Memory: search project knowledge'],
  ['about.png', '4  About: understand the architecture'],
  ['mobile.png', '5  The same workspace, responsive on mobile'],
];
await rm(frameRoot, { recursive: true, force: true });
await mkdir(frameRoot, { recursive: true });
let frame = 0;
for (const [file] of scenes) {
  for (let i = 0; i < 78; i += 1) {
    await copyFile(path.join(imageRoot, file), path.join(frameRoot, `frame-${String(frame).padStart(4, '0')}.png`));
    frame += 1;
  }
}
const args = ['-y', '-framerate', '30', '-i', path.join(frameRoot, 'frame-%04d.png'), '-vf', 'scale=1080:810:force_original_aspect_ratio=decrease,pad=1080:1080:(ow-iw)/2:(oh-ih)/2:color=0x08111e', '-an', '-c:v', 'libx264', '-pix_fmt', 'yuv420p', '-movflags', '+faststart', output];
const result = spawnSync('ffmpeg', args, { stdio: 'inherit' });
if (result.status !== 0) process.exit(result.status || 1);
console.log(output);
